/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 3) {
    let m = lines[0] - 0;
    let n = lines[1] - 0;
    let sequence = lines[2];

    getResult(m, n, sequence);
    lines.length = 0;
  }
});

function getResult(m, n, sequence) {
  boardCard = new Array(n).fill(0).map(() => m * 1.25);

  dict = { A: 1, B: 2, C: 8 };

  for (let i = 0; i < sequence.length; i++) {
    const need = 1.25 * dict[sequence[i]];
    for (let j = 0; j < n; j++) {
      if (boardCard[j] >= need) {
        boardCard[j] -= need;
        break;
      }
    }
  }

  boardCard.forEach((remain) => {
    unUsed = remain / 1.25;
    used = m - unUsed;
    console.log(
      new Array(used).fill(1).join("") + new Array(unUsed).fill(0).join("")
    );
  });
}

